void Skin_Matrix_SetQuaternion(MtxF* mf, f32* q) {
    f32 n;
    f32 xNorm;
    f32 yNorm;
    f32 zNorm;
    f32 wxNorm;
    f32 wyNorm;
    f32 wzNorm;
    f32 xxNorm;
    f32 xyNorm;
    f32 xzNorm;
    f32 yyNorm;
    f32 yzNorm;
    f32 zzNorm;

    n = 2.0f / ((q[3] * q[3]) + ((q[2] * q[2]) + ((q[1] * q[1]) + (q[0] * q[0]))));
    xNorm = q[0] * n;
    yNorm = q[1] * n;
    zNorm = q[2] * n;

    wxNorm = q[3] * xNorm;
    wyNorm = q[3] * yNorm;
    wzNorm = q[3] * zNorm;
    xxNorm = q[0] * xNorm;
    xyNorm = q[0] * yNorm;
    xzNorm = q[0] * zNorm;
    yyNorm = q[1] * yNorm;
    yzNorm = q[1] * zNorm;
    zzNorm = q[2] * zNorm;

    mf->xx = (1.0f - (yyNorm + zzNorm));
    mf->yx = (xyNorm + wzNorm);
    mf->zx = (xzNorm - wyNorm);
    mf->wx = 0.0f;
    mf->xy = (xyNorm - wzNorm);
    mf->yy = (1.0f - (xxNorm + zzNorm));
    mf->zy = (yzNorm + wxNorm);
    mf->wy = 0.0f;
    mf->xz = (yzNorm + wyNorm);
    mf->yz = (yzNorm - wxNorm);
    mf->zz = (1.0f - (xxNorm + yyNorm));
    mf->wz = 0.0f;
    mf->xw = 0.0f;
    mf->yw = 0.0f;
    mf->ww = 1.0f;
    mf->zw = 0.0f;
}

